function describe(n, depth) {
  const d = { name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if (n.cornerRadius !== undefined && n.cornerRadius !== 0) d.radius = n.cornerRadius;
  if (n.fills && n.fills.length) d.fills = n.fills.map(f => f.type==="SOLID" ? ("SOLID "+f.color.r.toFixed(2)+","+f.color.g.toFixed(2)+","+f.color.b.toFixed(2)+" a"+(f.opacity??1)) : f.type + (f.imageHash?(" hash:"+f.imageHash):"") + (f.scaleMode?(" "+f.scaleMode):""));
  if (n.strokes && n.strokes.length) d.strokes = n.strokes.map(f=>f.type);
  if (n.type==="TEXT") { d.text = n.characters; d.font = n.fontName.family+"/"+n.fontName.style; d.size = n.fontSize; }
  if (depth > 0 && n.children) d.kids = n.children.map(c=>describe(c, depth-1));
  return d;
}
