// Helper: create text node
function txt(parent, str, x, y, w, opts={}) {
  const t = figma.createText();
  parent.appendChild(t);
  t.x = x; t.y = y;
  t.fontName = { family: "DM Sans", style: opts.style || "Regular" };
  t.fontSize = opts.size || 14;
  t.fills = [{ type: "SOLID", color: opts.color || {r:0.1,g:0.1,b:0.1} }];
  if (w) { t.textAutoResize = "HEIGHT"; t.resize(w, t.height); }
  t.characters = str;
  if (opts.align) t.textAlignHorizontal = opts.align;
  if (opts.lh) t.lineHeight = { value: opts.lh, unit: "PIXELS" };
  return t;
}
// Helper: rect
function rect(parent, x, y, w, h, fill, r=0) {
  const rc = figma.createRectangle();
  parent.appendChild(rc);
  rc.x=x; rc.y=y; rc.resize(w,h);
  rc.fills = fill ? [{type:"SOLID",color:fill}] : [];
  if(r) rc.cornerRadius = r;
  return rc;
}
// Helper: instance of component by id
function inst(parent, compId, x, y, w, h) {
  const c = figma.getNodeById(compId);
  if(!c) return null;
  const i = c.createInstance();
  parent.appendChild(i);
  i.x=x; i.y=y;
  if(w&&h) i.resize(w,h);
  else if(w) i.resize(w, i.height);
  return i;
}

