function authScreen(name, x, isSignUp){
  const F=figma.createFrame(); F.name=name; F.resize(375,812); F.clipsContent=true; F.fills=[];
  F.x=x; F.y=0; page.appendChild(F);
  // background photo full-bleed
  const bg=inst('Photo_Auth_Background'); bg.resize(375,812); bg.x=0; bg.y=0; F.appendChild(bg);
  // overlay
  const ov=rect(375,812,{fill:[0.04,0.05,0.07],opacity:0.62}); ov.x=0; ov.y=0; F.appendChild(ov);
  // status bar white
  const sb=statusBarWhite(); sb.x=0; sb.y=0; F.appendChild(sb);
  // logo + wordmark
  const lm=inst('Logo_Mark'); lm.resize(34,34); lm.x=(375-150)/2; lm.y=118; F.appendChild(lm);
  const wm=txt('Audio',{size:30,style:'Bold',color:[1,1,1]}); wm.x=(375-150)/2+42; wm.y=118; F.appendChild(wm);
  const tg=txt('It’s modular and designed to last',{size:14,color:[1,1,1],opacity:0.9});
  tg.textAlignHorizontal='CENTER'; tg.resize(311,tg.height); tg.x=32; tg.y=172; F.appendChild(tg);
  // fields
  const f1=inst('Auth Field'); f1.x=24; f1.y=isSignUp?300:284; F.appendChild(f1);
  const f2=inst('Auth Field'); f2.x=24; f2.y=isSignUp?362:362; F.appendChild(f2);
  const l1=f1.findOne(n=>n.type==='TEXT'); const l2=f2.findOne(n=>n.type==='TEXT');
  // set placeholders: first Auth Field instance label
  if(l1) l1.characters='Email'; if(l2) l2.characters='Password';
  const i1=f1.findOne(n=>n.type==='INSTANCE'); const i2=f2.findOne(n=>n.type==='INSTANCE');
  if(i1){ const mail=inst('Icon_Mail'); mail.resize(20,20); mail.x=i1.x; mail.y=i1.y; i1.remove(); f1.appendChild(mail); }
  if(i2){ const lock=inst('Icon_Lock'); lock.resize(20,20); lock.x=i2.x; lock.y=i2.y; i2.remove(); f2.appendChild(lock); }
  let y=f2.y+62;
  if(!isSignUp){
    const fp=txt('Forgot Password',{size:13,style:'Medium',color:[1,1,1]}); fp.textAlignHorizontal='RIGHT'; fp.resize(327,fp.height); fp.x=24; fp.y=y; F.appendChild(fp); y+=34;
  } else {
    // social row
    const orr=txt('—  or continue with  —',{size:12,color:[1,1,1],opacity:0.85}); orr.textAlignHorizontal='CENTER'; orr.resize(327,orr.height); orr.x=24; orr.y=y; F.appendChild(orr); y+=30;
    const logos=['Logo_Apple','Logo_Google','Logo_Facebook'];
    logos.forEach((n,i)=>{ const b=inst('Social Button'); b.x=24+i*(105+11); b.y=y; F.appendChild(b);
      const lg=b.findOne(m=>m.type==='INSTANCE'); const logo=inst(n); logo.resize(22,22); logo.x=lg.x; logo.y=lg.y; lg.remove(); b.appendChild(logo);
    });
    y+=72;
  }
  // button
  const btn=inst('Button'); btn.x=24; btn.y=y; btn.resize(327,50); F.appendChild(btn);
  const bt=btn.findOne(n=>n.type==='TEXT'); if(bt) bt.characters=isSignUp?'Sign Up':'Sign In';
  // bottom text
  const btTxt = isSignUp? 'Already have an account? Sign In here' : 'Don’t have an account? Sign Up here';
  const link=txt(btTxt,{size:13,color:[1,1,1]}); link.textAlignHorizontal='CENTER'; link.resize(327,link.height); link.x=24; link.y=y+74; F.appendChild(link);
  // make the "here" part? keep single text; ok
  // home indicator
  const hi=inst('Home Indicator'); hi.resize(375,34); hi.x=0; hi.y=812-34; F.appendChild(hi);
  return F;
}

