    if(kb!==ka) return kb-ka;
    return parseInt(a.id)-parseInt(b.id);
  });
  arr.forEach((n,i)=>{ if(i===0){keepIds.add(n.id); kept.push(n.id+' '+n.name+' kids='+n.children.length);} else removed.push(n.id+' '+n.name+' kids='+n.children.length); });
}
for(const c of page.children){
  if(c.name.match(/^\d\d_/) && !keepIds.has(c.id)){
    try{c.remove();}catch(e){}
  }
}
return {kept, removed};

